class DiagnosticInterface21B(object):

    def get_snapshot(self, target_file_name, coverage="Full", force=True, timeout=360, reg_exp_filter=None,
                     reason=None, network_cell_dns=None, detailed_output=False):

        """
        Order snapshot creation, collection and save it in local path.

        :param str target_file_name: Location where snapshot shall be saved.
        :param str coverage: Full, Minor or HealthCheck (only for SRAN) snapshot scope. defaults set to Full.
        :param bool force: True or False to force snapshot creation.
        :param int timeout: Timeout for the operation. Note: CLI request for snapshot is not cancelled after timeout.
                            For cancel please call snapshot_cancel()
        :param str reg_exp_filter: (optional) optional, since SBTS18, Data "regExpFilter" will be ignored if coverage is
                                 "HealthCheck"
        :param str reason: (optional) reason for the operation.
        :param list[str] network_cell_dns: (optional) list of str of network cell distnames (only for SRAN builds)
        :param bool detailed_output: return full request response when True, defaults set to False.
        :raises AdminApiProcedureFailureException: If response status equals 'failed' it returns that exception.

        :return str: Status of the operation.
                      More details: https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-snapshot.html
        """
        parameters = {
            "coverage": coverage,
            "force": "Yes" if force else "No",
            "regExpFilter": reg_exp_filter,
            "reason": reason,
            "networkCellDNs": network_cell_dns,

        }

        parameters = {k: v for k, v in parameters.items() if v is not None}

        response = self._api_client.execute_customer_procedure("snapshot", parameters, timeout,
                                                               output_file_name=target_file_name)

        return response if detailed_output else response.get(self._provided_content.request_message)

    def get_remote_snapshot(self, coverage='Full', reg_exp_filter=None, network_cell_dns=None,
                            reason=None, timeout=100):
        """
        Order snapshot creation, collection and save in remote host.

        :param str coverage: It defines snapshot scope. It should be 'Full' or 'Minor'. Default equals 'Full'.
        :param str reg_exp_filter: (Optional) Regular expression for filtering snapshot.
        :param list network_cell_dns: (Optional) List of paths to Network Cell DNs.
                                      Example: ["/MRBTS-1/RAT-1/RUNTIME_VIEW-4/MRBTS_R-4/LNBTS_R-1/LNCEL_R-2"].
        :param str reason: (Optional) Reason of snapshot execution.
        :param Union[int,str] timeout: Timeout for the operation.
        :raises AdminApiProcedureFailureException: If response status equals 'failed' it returns that exception.

        :return str: It returns reason message.
                More details: https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-remoteSnapshot.html
        """
        parameters = {'coverage': coverage, 'regExpFilter': reg_exp_filter,
                      'networkCellDNs': network_cell_dns, 'reason': reason}
        parameters = {key: value for key, value in parameters.items() if value is not None}

        result = self._api_client.execute_procedure('remoteSnapshot', parameters, timeout)
        return result

    def perform_eac_faults_test(self, dist_name, timeout=100):
        """
        Perform execution of EAC Faults Test. This keyword will wait for change on EAC port to ON or OFF, if change
            shall not happen, this keyword will timeout.

        To run keyword in background (ie. to wait for EAC change while you modify the EAC state):
            >>> task1 = coam_admin_instance.run_keyword_in_background(
            >>>     coam_admin_instance,
            >>>     "perform_eac_faults_test",
            >>>     dist_name="/MRBTS-1/RAT-1/BTS_L-1/BTS_CONF-1/NP-13/SCF-1/MRBTS_A-50308/EQM_A-1/APEQM_A-1/CABINET_A-1/SMOD_A-1/EAC_IN_A-1",
            >>>     timeout=10)
        To pool if task is finished:
            >>> task1.finished
            >>> True
        To collect result
            >>> task1.result

        :param str dist_name: EAC dist name
                             ie. "/MRBTS-1/RAT-1/BTS_L-1/BTS_CONF-1/NP-1/SCF-1/MRBTS_A-1/EQM_A-1/APEQM_A-1/CABINET_A-1/SMOD_A-1/EAC_IN_A-1"
        :param Union[int,str] timeout: Timeout for the operation.
        :return dict: Test execution details. Example: {"faultState":"ON", "testResult":"OK"}
                     More details: https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-eacFaultsTest.html
        :raises DataNotAvailable: Raised if operation is invalid from Node-B side.
        """
        parameters = {"eacInDN": dist_name}
        result = self._api_client.execute_infomodel_request(
            "eacFaultsTest", parameters, timeout)

        if result is None:
            raise DataNotAvailable("Fault test result has not been provided by M-Plane.")
        return result

    def perform_eac_controls_test(self, dist_name, target_line_state, timeout=100):
        """
        Perform execution of EAC Controls Test.

        :param str dist_name: EAC dist name
                             ie. "/MRBTS-1/RAT-1/RUNTIME_VIEW-1/MRBTS_R-1/EQM_R-1/APEQM_R-1/CABINET_R-1/SMOD_R-1/EAC_R-27"
        :param str target_line_state: Target Line State: on or off
        :param Union[int,str] timeout: Timeout for the operation.
        :return str: Test execution result. Example: "Rejected", "Failed", "Succeeded", "Unexpected"
                     More details: https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-eacControlsTest.html
        :raises: ValueError if target_line_state does not meet one of the given values.
        :raises DataNotAvailable: Raised if operation is invalid from Node-B side.

        """
        if target_line_state not in ['on', 'off']:
            raise ValueError('target_line_state parameter needs to be "on" or "off"')

        parameters = {"targetDN": dist_name, "targetLineState": target_line_state}
        result = self._api_client.execute_procedure(
            "eacControlsTest", parameters, timeout)

        if result is None:
            raise DataNotAvailable("Fault controls test result has not been provided by M-Plane.")
        return result

    def watch_5g_uplink_ccm_test_results(self, nr_cell_rdn, timeout=100, finalizer_timeout=10, get_updates=False):
        """
        Provides possibility to observe Uplink CCM Test Results in real time.

        :param str nr_cell_rdn: distName of nrcell_rDN object to watch ongoing nr uplink CCM test results
        :param int timeout: Timeout for the operation.
        :param int finalizer_timeout: Time for finalizing. Defaults set to 10.
        :param bool get_updates: Keyword will return all of the test results updates if true, last one otherwise.

        :return: It returns dict with data. Will return array of results if get_updates set to True.

        Example response

        ::

          {
                "timeReceived": 33333,
                "type": "Prach",
                "detectedCounter": 0,
                "missedCounter": 1,
                "falseCounter": 20,
                "idlePeriodCounter": 7,
                "noPaCounter": 15,
                "wrongPaCounter": 20,
                "wrongTimingCounter": 1
            }

        More details:
        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-watch5GUplinkCCMTestResults.html
        """
        parameters = {'nrcell_rDN': nr_cell_rdn}

        response = self._api_client.execute_endless_procedure('watch5GUplinkCCMTestResults',
                                                              parameters=parameters,
                                                              timeout=timeout,
                                                              finalizer_timeout=finalizer_timeout,
                                                              get_updates=get_updates)
        if response is None:
            raise DataNotAvailable("Watching Uplink CCM Test Results has not bee provided by M-Plane.")

        if get_updates:
            return response
        else:
            return self._api_client.check_if_response_status_is_expected(response, "update").get_payload()

