    def launch_troubleshooting_script(self, script_name, output_file_name, cell_list=None, bbmod_list=None, rmod_list=None,
                                      free_parameters=None, timeout=60, detailed_output=False):
        """
        Launch troubleshooting script.

        :param string script_name: Mandatory, name of troubleshooting script.
        :param string string output_file_name: Path to script snapshot.
        :param list cell_list: optional, <list of LNCELs or NRCELLs distname>,
         e.g. ["MRBTS-5998/LNBTS-5998/LNCEL-1", "MRBTS-5998/NRBTS-5998/NRCELL-3"]
        :param list bbmod_list: optional, <list of BBMODs distname>,
         e.g. ["MRBTS-5998/EQM-1/APEQM-1/CABINET-1/BBMOD-1","MRBTS-5998/EQM-1/APEQM-1/CABINET-1/BBMOD-2"]",
        :param list rmod_list: optional, <list of RMODs distname>,
         e.g. ["MRBTS-5998/EQM-1/APEQM-1/RMOD-1","MRBTS-5998/EQM-1/APEQM-1/RMOD-2"],
        :param string free_parameters: optional, <freeParameters>. See docs for more details.
        :param int timeout: Time in seconds to wait for positive procedure result.
        :param bool detailed_output: Return full request response when True, defaults set to False.
        :return dict: Procedure feedback.

        More details:
        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-launchTroubleshootingScript.html
        """

        parameters = {"scriptName": script_name}

        if cell_list:
            cell_list = wrap_with_list(cell_list)
            parameters["cells"] = cell_list
        if bbmod_list:
            bbmod_list = wrap_with_list(bbmod_list)
            parameters["bbmods"] = bbmod_list
        if rmod_list:
            rmod_list = wrap_with_list(rmod_list)
            parameters["rmods"] = rmod_list
        if free_parameters:
            parameters["freeParameters"] = free_parameters

        response = self._api_client.execute_customer_procedure("launchTroubleshootingScript", parameters, timeout,
                                                               output_file_name=output_file_name)
        return response if detailed_output else response.get(self._provided_content.request_message)

